  {"id":"ugc-exp-2026-12-s2-98","xp":"ugc-exp-2026-12-s2","set":"2026-12-s2","n":98,"u":"p2u9","t":5,"f":"passage","q":"The maximum number of hosts that can be assigned addresses in each subnet is:","o":["64","126","30","62"],"ans":"D","pas":"A host on the Internet is configured with the IP address 172.16.45.130 and the subnet mask 255.255.255.192. The organisation owns the entire classful network to which this address belongs and has divided it into equal-sized subnets using this mask (all subnets, including the first and the last, are usable)."},
  {"id":"ugc-exp-2026-12-s2-99","xp":"ugc-exp-2026-12-s2","set":"2026-12-s2","n":99,"u":"p2u9","t":5,"f":"passage","q":"To which class does the address 172.16.45.130 belong, and what is its default subnet mask?","o":["Class A, 255.0.0.0","Class B, 255.255.0.0","Class C, 255.255.255.0","Class B, 255.255.255.0"],"ans":"B","pas":"A host on the Internet is configured with the IP address 172.16.45.130 and the subnet mask 255.255.255.192. The organisation owns the entire classful network to which this address belongs and has divided it into equal-sized subnets using this mask (all subnets, including the first and the last, are usable)."},
  {"id":"ugc-exp-2026-12-s2-100","xp":"ugc-exp-2026-12-s2","set":"2026-12-s2","n":100,"u":"p2u9","t":5,"f":"passage","q":"How many subnets of this size can the organisation create from its classful network?","o":["64","256","1024","512"],"ans":"C","pas":"A host on the Internet is configured with the IP address 172.16.45.130 and the subnet mask 255.255.255.192. The organisation owns the entire classful network to which this address belongs and has divided it into equal-sized subnets using this mask (all subnets, including the first and the last, are usable)."}
